const bgMusic = new Audio('chamber.mp3'); 
bgMusic.loop = true; 
bgMusic.volume = 0.05; 

const bossMusic = new Audio('boss_battle_music.mp3');
bossMusic.loop = true;
bossMusic.volume = 0.10;

const finalBossMusic = new Audio('final_boss_music.mp3');
finalBossMusic.loop = true;
finalBossMusic.volume = 0.12; // slightly louder, it's the final fight    

const sfxMilestone = new Audio('streak.wav');
const sfxVictory = new Audio('victory.wav');
const sfxBossHit = new Audio('boss_hit.wav');
      sfxBossHit.volume = 0.5;
const sfxCorrect = new Audio('ding.wav');
      sfxCorrect.volume = 0.25;
const sfxWrong = new Audio('mistake.wav');
      sfxWrong.volume = 0.4;

const hallwayImages = [
    "hallway1.webp",
    "hallway2.webp",
    "hallway3.webp"
];

let soundEnabled = true;
const SOUND_PREF_KEY = "marketGateSoundEnabled";

function updateSoundToggle(){
  const button = document.getElementById("soundToggle");
  if(!button) return;
  button.innerText = soundEnabled ? "Sound On" : "Sound Off";
}

function setAllGameAudioMuted(isMuted){
  [bgMusic, bossMusic, finalBossMusic, sfxMilestone, sfxVictory, sfxBossHit, sfxCorrect, sfxWrong]
    .filter(Boolean)
    .forEach(audio => {
      audio.muted = isMuted;
    });
}

function toggleGameSound(){
  soundEnabled = !soundEnabled;

  localStorage.setItem(SOUND_PREF_KEY, soundEnabled ? "true" : "false");
  setAllGameAudioMuted(!soundEnabled);
  updateSoundToggle();

  if(soundEnabled){
      resumeCurrentMusic();
  } else {
      pauseAllGameMusic();
  }
}

function restoreSoundSetting(){
  const saved = localStorage.getItem(SOUND_PREF_KEY);

  soundEnabled = saved !== "false";

  setAllGameAudioMuted(!soundEnabled);
  updateSoundToggle();
}

restoreSoundSetting();

setGameControlsVisible(false);

function setGameControlsVisible(isVisible){
    document.body.classList.toggle("game-active", !!isVisible);
}

function pauseAllGameMusic(){
    [bgMusic, bossMusic, finalBossMusic].filter(Boolean).forEach(audio => {
        audio.pause();
    });
}

function safePlay(audio){
    if(!audio || !soundEnabled) return Promise.resolve();

    audio.muted = false;

    return audio.play().catch(error => {
        console.warn("Audio play blocked:", error);
    });
}

function resumeCurrentMusic(){
    if(typeof currentMusic !== "undefined"){
        if(currentMusic === "boss") return safePlay(bossMusic);
        if(currentMusic === "finalBoss") return safePlay(finalBossMusic);
        if(currentMusic === "exploration") return safePlay(bgMusic);
    }

    return safePlay(bgMusic);
}

