function syncRealmAttemptState(){
    if(!modeAllowsRealmProgress()) return;

    localStorage.setItem(REALM_STARTED_KEY, "true");

    if(isRealmMissionComplete()){
        localStorage.setItem(REALM_STATUS_KEY, "restored");
        localStorage.setItem(REALM_ROOM_KEY, "30");
        return;
    }

    localStorage.setItem(REALM_STATUS_KEY, "contested");
    localStorage.setItem(REALM_ROOM_KEY, String(room || 1));
