market-gate.resourceSource:
const INSTRUCTIONAL_RESOURCE_TYPE_LABELS = {
    "video": "Lecture Video",
    "worked-problem": "Worked-Problems Video",
    "slides": "Lecture Slides",
    "other": "Course Material"
};
const INSTRUCTIONAL_RESOURCE_TYPE_ORDER = {
    "video": 1,
    "worked-problem": 2,
    "slides": 3,
    "other": 4
};

function getInstructionalResourceConfig(){
    const config = window.INSTRUCTIONAL_RESOURCES;
    if(!config || typeof config !== "object"){
        console.warn("[Market Gate] Instructional-resource catalog is unavailable.");
        return null;
    }
    return validateInstructionalResourceConfig(config) ? config : null;
}

function validateInstructionalResourceConfig(config){
    if(!config || typeof config !== "object") return false;
    if(!config.chapters || typeof config.chapters !== "object"){
        console.warn("[Market Gate] Instructional-resource catalog has no chapters object.");
        return false;
    }
    if(config.objectives && typeof config.objectives !== "object"){
        console.warn("[Market Gate] Instructional-resource objectives must be an object; ignoring objective mappings.");
    }
    return true;
}

function normalizeLearningObjectiveId(value){
    const match = String(value || "").trim().match(/(?:LO\s*)?(\d+)\s*[._\-\s]\s*(\d+)/i);
    return match ? `${Number(match[1])}.${Number(match[2])}` : null;
}

function getChapterFromLearningObjective(value){
    const normalized = normalizeLearningObjectiveId(value);
    return normalized ? normalized.split(".")[0] : null;
}

function getObjectiveResourceMapping(config, normalizedObjective){
    if(!config || !config.objectives || typeof config.objectives !== "object") return null;
    return Object.entries(config.objectives).find(([id]) => normalizeLearningObjectiveId(id) === normalizedObjective)?.[1] || null;
}

function isSafeInstructionalResourceUrl(value){
    if(typeof value !== "string" || !value.trim()) return false;
    const url = value.trim();
    if(/^https:\/\//i.test(url)){
        try { return new URL(url).protocol === "https:"; }
        catch(error) { console.warn("[Market Gate] Ignoring instructional resource with an invalid URL.", error); return false; }
    }
    return /^resources\/(?:[^\\/:?#]+\/)*[^\\/:?#]+\.(?:ppt|pptx|pdf)$/i.test(url)
        && !/(?:^|\/)\.\.(?:\/|$)/.test(url);
}

function resolveInstructionalResourceById(config, resourceId){
    if(!config || !resourceId) return null;
    for(const chapter of Object.values(config.chapters || {})){
        for(const resource of (Array.isArray(chapter?.resources) ? chapter.resources : [])){
            if(resource?.id !== resourceId) continue;
            if(typeof resource.title !== "string" || !resource.title.trim() || !isSafeInstructionalResourceUrl(resource.url)){
                console.warn(`[Market Gate] Ignoring malformed instructional resource: ${resourceId}`);
                return null;
            }
            return resource;
        }
    }
    console.warn(`[Market Gate] Instructional resource ID was not found: ${resourceId}`);
    return null;
}

function getRecommendedResources(weakObjectiveIds){
    const config = getInstructionalResourceConfig();
    if(!config || !Array.isArray(weakObjectiveIds) || weakObjectiveIds.length === 0) return [];

    const settings = config.settings && typeof config.settings === "object" ? config.settings : {};
    const maximum = Math.max(1, Math.min(3, Number(settings.maximumRecommendations) || 3));
    const allowFallback = settings.enableChapterFallback !== false;
    const selected = new Map();

    function addResource(resource){
        if(!resource?.id || selected.has(resource.id) || !isSafeInstructionalResourceUrl(resource.url)) return;
        selected.set(resource.id, resource);
    }

    weakObjectiveIds.forEach(objectiveId => {
        if(selected.size >= maximum) return;
        const normalized = normalizeLearningObjectiveId(objectiveId);
        if(!normalized) return;
        const mapping = getObjectiveResourceMapping(config, normalized);
        (Array.isArray(mapping?.resourceIds) ? mapping.resourceIds : [])
            .map(id => resolveInstructionalResourceById(config, id)).filter(Boolean).forEach(addResource);

        if(!allowFallback || selected.size >= maximum) return;
        const chapter = config.chapters?.[getChapterFromLearningObjective(normalized)];
        if(!chapter || !Array.isArray(chapter.resources)){
            console.warn(`[Market Gate] No chapter fallback is available for LO ${normalized}.`);
            return;
        }
        const fallbackResources = Array.isArray(chapter.fallbackResourceIds) ? chapter.fallbackResourceIds.map(id => resolveInstructionalResourceById(config, id)).filter(Boolean) : chapter.resources.slice().sort((a, b) => (Number(a?.priority) || 999) - (Number(b?.priority) || 999));
        fallbackResources.forEach(addResource);
    });

    return Array.from(selected.values()).slice(0, maximum);
}
function getWeakLearningObjectiveIds(report){
    return report?.hasObjectiveWeakness && Array.isArray(report.weakestObjectives)
        ? report.weakestObjectives.map(entry => entry?.key).filter(Boolean)
        : [];
}

function getInstructionalObjectiveTitle(objectiveId){
    const normalized = normalizeLearningObjectiveId(objectiveId);
    const config = getInstructionalResourceConfig();
    const mappedTitle = normalized ? getObjectiveResourceMapping(config, normalized)?.title : "";
    return mappedTitle || (normalized ? `LO ${normalized}` : formatMasteryLabel(objectiveId));
}

function getInstructionalResourceActionLabel(resource){
    if(typeof resource?.actionLabel === "string" && resource.actionLabel.trim()) return resource.actionLabel;
    return resource?.type === "slides" ? "Open Slides" : "Watch Video";
}

function renderInstructionalResourceCards(resources){
    return resources.map(resource => {
        const type = INSTRUCTIONAL_RESOURCE_TYPE_LABELS[resource.type] || INSTRUCTIONAL_RESOURCE_TYPE_LABELS.other;
        const description = typeof resource.description === "string" && resource.description.trim()
            ? `<p class="resource-card-description">${escapeHTML(resource.description)}</p>` : "";
        return `<article class="resource-card"><div class="resource-card-header"><h4 class="resource-card-title">${escapeHTML(resource.title)}</h4><span class="resource-card-type">${escapeHTML(type)}</span></div>${description}<a class="resource-card-link" href="${escapeHTML(resource.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(getInstructionalResourceActionLabel(resource))}<span class="sr-only">: ${escapeHTML(resource.title)}</span></a></article>`;
    }).join("");
}

function renderInstructionalResourceSection(report){
    const weakObjectives = getWeakLearningObjectiveIds(report);
    if(!weakObjectives.length) return "";
    const resources = getRecommendedResources(weakObjectives);
    const intro = "Based on the weakest learning objectives in this run, start with these materials before your next attempt.";

    if(!resources.length){
        return `<div class="mastery-section resource-recommendation-section"><h3>Recommended Review</h3><p class="resource-recommendation-intro">${escapeHTML(intro)}</p><p class="mastery-empty">No review material is available for these objectives yet.</p></div>`;
    }

    return `<div class="mastery-section resource-recommendation-section"><h3>Recommended Review</h3><p class="resource-recommendation-intro">${escapeHTML(intro)}</p><div class="resource-recommendation-list">${renderInstructionalResourceCards(resources)}</div><div class="mastery-actions"><button class="continue-btn" type="button" onclick="openInstructionalReviewScreen()">Review Materials</button></div></div>`;
}

function openInstructionalReviewScreen(){
    const gameBox = document.getElementById("gameBox");
    if(!gameBox) return;
    const report = getMasteryReportData();
    const weakObjectives = getWeakLearningObjectiveIds(report);
    const resources = getRecommendedResources(weakObjectives);
    const objectiveList = weakObjectives.length
        ? `<ul class="review-objective-list">${weakObjectives.map(id => `<li>${escapeHTML(getInstructionalObjectiveTitle(id))}</li>`).join("")}</ul>`
        : `<p class="mastery-empty">No learning objective is available for review from this report.</p>`;
    const resourceContent = resources.length
        ? `<p class="resource-recommendation-intro">Based on the weakest learning objectives in this run, start with these materials before your next attempt.</p><div class="resource-recommendation-list">${renderInstructionalResourceCards(resources)}</div>`
        : `<p class="mastery-empty">No review material is available for these objectives yet.</p>`;

    gameBox.innerHTML = `<section id="instructionalReviewScreen" class="mastery-report-screen review-materials-screen" aria-labelledby="instructionalReviewTitle"><h1 id="instructionalReviewTitle" class="mastery-report-title" tabindex="-1">REVIEW BEFORE YOUR NEXT ATTEMPT</h1><p class="mastery-report-subtitle">Use these materials to reinforce the concepts that showed the weakest signal in this run.</p><div class="mastery-section"><h2>Learning Objectives to Review</h2>${objectiveList}</div><div class="mastery-section"><h2>Recommended Materials</h2>${resourceContent}</div><div class="mastery-actions"><button class="continue-btn" type="button" onclick="returnToMasteryReport()">Return to Mastery Report</button><button class="continue-btn secondary-modal-btn" type="button" onclick="location.reload()">Replay Mission</button><button class="continue-btn secondary-modal-btn" type="button" onclick="returnToModeSelectFromRun()">Choose Another Battle</button></div></section>`;
    document.getElementById("instructionalReviewTitle")?.focus?.();
}

function returnToMasteryReport(){
    showMasteryReportScreen(true);
}

market-gate.highScoreFunction:
function updateHighScores(newTimeMs) {
    let scores = JSON.parse(localStorage.getItem("marketGateHighScores")) || [];
    scores.push({ name: username, time: newTimeMs, date: new Date().toLocaleDateString() });

    // Sort by time (lowest/fastest first) and keep top 5
    scores.sort((a, b) => a.time - b.time);
    scores = scores.slice(0, 5);

    localStorage.setItem("marketGateHighScores", JSON.stringify(scores));
    return scores;
}

market-gate.pseudonymFunction:
function generatePseudonymFromSeed(seed) {
    const titles = [
        "Axiom", "Ledger", "Vector", "Meridian", "Signal", "Cipher",
        "Frontier", "Equity", "Oracle", "Index", "Summit", "Nexus",
        "Vault", "Prism", "Civic", "Astral", "Beacon", "Horizon"
    ];

    const roles = [
        "Appraiser", "Cartographer", "Arbiter", "Custodian", "Warden", "Registrar",
        "Archivist", "Surveyor", "Magistrate", "Keeper", "Analyst", "Mediator",
        "Steward", "Scribe", "Sentinel", "Marshal", "Seeker", "Auditor"
    ];

    let hash = 0;
    const cleanSeed = String(seed || "market-gate").trim().toLowerCase();

    for (let i = 0; i < cleanSeed.length; i++) {
        hash = ((hash << 5) - hash) + cleanSeed.charCodeAt(i);
        hash |= 0;
    }

    const positiveHash = Math.abs(hash);

    const title = titles[positiveHash % titles.length];
    const role = roles[Math.floor(positiveHash / titles.length) % roles.length];
    const number = 1000 + (positiveHash % 9000);

    return `${title}${role}${number}`;
}

market-gate.streakFunction:
function handleStreakVisuals() {
    let streakMsg = "";
    let streakColor = "#f0c86a";

    if (streak === 5) {
        streakMsg = `<span class="streak"><img src="streaksignal.webp" class="streak-icon" alt="" aria-hidden="true">DEMAND SIGNAL FOUND</span>`;
        streakColor = "#f0c86a";
    }
    else if (streak === 10) {
        streakMsg = `<span class="streak"><img src="streakkey.webp" class="streak-icon" alt="" aria-hidden="true">ENTRY KEY CLAIMED</span>`;
        streakColor = "#38bdf8";
    }
    else if (streak === 20) {
        streakMsg = `<span class="streak"><img src="streakseal.webp" class="streak-icon" alt="" aria-hidden="true">EQUILIBRIUM SEALED</span>`;
        streakColor = "#f5e6b8";
    }

    if (streakMsg) {
        sfxMilestone.currentTime = 0;
        sfxMilestone.play();
        document.getElementById("streakDisplay").innerHTML = streakMsg;
        document.getElementById("streakDisplay").style.color = streakColor;
    } else if (streak > 0) {
        document.getElementById("streakDisplay").innerText = `Streak: ${streak}`;
        document.getElementById("streakDisplay").style.color = "#f0c86a";
    }
}

