function getAreaName(r) {
    if (r <= 9) return "Stabilization Briefing Corridor";
    if (r === 10) return "The Policy Sentinel’s Chamber";
    if (r <= 19) return "AD-AS Stabilization Wing";
    if (r === 20) return "The Stabilization Regent's Gate";
    if (r <= 25) return "Fiscal-Monetary Transmission Floor";
    if (r <= 29) return "Phillips Curve Tribunal";
    return "The Custodian’s Final Chamber";
}

