    const safeAccuracy = Number.isFinite(Number(accuracy)) ? Number(accuracy) : 0;
    const safeRoom = Number.isFinite(Number(reachedRoom)) ? Number(reachedRoom) : 0;

    updateRealmMaxStat("stabilizationProtocolTimedBestRoom", safeRoom);
    updateRealmMaxStat("stabilizationProtocolTimedBestAccuracy", safeAccuracy);

    updateRealmMaxStat("economicRealm_timedBestRoom", safeRoom);
    updateRealmMaxStat("economicRealm_timedBestAccuracy", safeAccuracy);

